<?php namespace App\Livewire\Public; use App\Actions\CreateOrderAction; use App\Models\FoodItem; use App\Models\Order; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class MenuShow extends Component { use AuthorizesRequests; public FoodItem $foodItem; public int $quantity = 1; public string $pickupTime = '12:30 PM'; public function mount(FoodItem $foodItem): void { $this->foodItem = $foodItem->load(['stall', 'category']); } public function placeOrder(CreateOrderAction $action) { $this->authorize('create', Order::class); $this->validate(['quantity' => ['required', 'integer', 'min:1', 'max:20'], 'pickupTime' => ['required', 'string', 'max:50']]); $action->execute(auth()->user(), $this->foodItem->stall_id, $this->pickupTime, [['food_item_id' => $this->foodItem->id, 'quantity' => $this->quantity]]); session()->flash('status', 'Pre-order placed successfully! Pay at the stall upon pickup.'); return redirect()->route('orders.index'); } public function render() { return view('livewire.public.menu-show'); } }